// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class BulkCapacityPolicyTest {

	@Test
	void defaultRoundsUpAndCapsWithoutOverflow() {
		BulkCapacityPolicy policy = BulkCapacityPolicy.defaultHeadroom();
		assertEquals(0L, policy.additionalItems(0L));
		assertEquals(1L, policy.additionalItems(1L));
		assertEquals(2L, policy.additionalItems(11L));
		assertEquals(100_000L, policy.additionalItems(999_991L));
		assertEquals(100_000L, policy.additionalItems(Long.MAX_VALUE));
	}

	@Test
	void factorIsTotalCountAndRoundsFractionalGrowth() {
		assertEquals(0L, BulkCapacityPolicy.factor(1.0).additionalItems(11L));
		assertEquals(6L, BulkCapacityPolicy.factor(1.5).additionalItems(11L));
		assertEquals(11L, BulkCapacityPolicy.factor(2.0).additionalItems(11L));
		assertEquals(22L, BulkCapacityPolicy.factor(3.0).additionalItems(11L));
		assertEquals(0L, BulkCapacityPolicy.factor(3.0).additionalItems(0L));
		assertThrows(IllegalArgumentException.class,
				() -> BulkCapacityPolicy.factor(2.0).additionalItems(Long.MAX_VALUE));
	}

	@Test
	void minimumIsIndependentByteFloorAndTokensRoundTrip() {
		BulkCapacityPolicy minimum = BulkCapacityPolicy.parse("min:64MiB");
		assertEquals(64L * 1024 * 1024, minimum.minimumBytes());
		assertEquals(0L, minimum.additionalItems(1_000_000L));
		for (String token : new String[] { "default", "min:1", "factor:1", "factor:1.25", "factor:3.0" }) {
			BulkCapacityPolicy policy = BulkCapacityPolicy.parse(token);
			assertEquals(policy, BulkCapacityPolicy.parse(policy.toString()));
		}
	}

	@Test
	void extremeFactorUsesCompactExactTokenBeforeCountOverflow() {
		BulkCapacityPolicy policy = BulkCapacityPolicy.parse("factor:1e1000000");
		assertEquals("factor:1E+1000000", policy.toString());
		assertEquals(policy, BulkCapacityPolicy.parse(policy.toString()));
		assertEquals(0L, policy.additionalItems(0L));
		assertThrows(IllegalArgumentException.class, () -> policy.additionalItems(1L));
	}

	@Test
	void emptyFactorCountDoesNotExpandItsExponent() {
		BulkCapacityPolicy policy = BulkCapacityPolicy.parse("factor:1e2147483647");
		assertEquals(0L, policy.additionalItems(0L));
		assertThrows(IllegalArgumentException.class, () -> policy.additionalItems(1L));
	}

	@ParameterizedTest
	@ValueSource(strings = { "", "unknown", "min:0", "min:-1", "min:99999999999999999999GiB",
			"factor:0.9", "factor:NaN", "factor:Infinity", "factor:-Infinity" })
	void rejectsInvalidPolicies(String token) {
		assertThrows(IllegalArgumentException.class, () -> BulkCapacityPolicy.parse(token));
	}

	@ParameterizedTest
	@ValueSource(doubles = { Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY, -1.0, 0.999 })
	void rejectsInvalidApiFactors(double factor) {
		assertThrows(IllegalArgumentException.class, () -> BulkCapacityPolicy.factor(factor));
	}
}
